42:     @Test
43:     public void testCreate() {
44:         final Throwable failure = new RuntimeException("Expected exception");
45:         final long timestamp = System.currentTimeMillis();
46:         final TaskManagerLocation taskManagerLocation = new LocalTaskManagerLocation();
47:         final AccessExecution execution =
48:                 TestingAccessExecution.newBuilder()
49:                         .withErrorInfo(new ErrorInfo(failure, timestamp))
50:                         .withTaskManagerLocation(taskManagerLocation)
51:                         .build();
52:         final String taskName = "task name";
53:         final Map<String, String> failureLabels = Collections.singletonMap("key", "value");
54: 
55:         final ExceptionHistoryEntry entry =
56:                 ExceptionHistoryEntry.create(
57:                         execution, taskName, CompletableFuture.completedFuture(failureLabels));
58: 
59:         assertThat(
60:                 entry.getException().deserializeError(ClassLoader.getSystemClassLoader()),
61:                 is(failure));
62:         assertThat(entry.getTimestamp(), is(timestamp));
63:         assertThat(entry.getFailingTaskName(), is(taskName));
64:         assertThat(
65:                 entry.getTaskManagerLocation(), isArchivedTaskManagerLocation(taskManagerLocation));
66:         assertThat(entry.isGlobal(), is(false));
67:         assertThat(entry.getFailureLabels(), is(failureLabels));
68:     }
